// WorkspaceServiceHandler is an implementation of the tammy.v1.WorkspaceService service.
type WorkspaceServiceHandler interface {
	// CreateWorkspace creates pending encrypted setup and returns one-time recovery material.
	CreateWorkspace(context.Context, *connect.Request[v1.CreateWorkspaceRequest]) (*connect.Response[v1.CreateWorkspaceResponse], error)
	// ConfirmRecovery is a fresh rate-limited setup challenge.
	ConfirmRecovery(context.Context, *connect.Request[v1.ConfirmRecoveryRequest]) (*connect.Response[v1.ConfirmRecoveryResponse], error)
	// UnlockWorkspace is a fresh rate-limited passphrase or remembered-key challenge.
	UnlockWorkspace(context.Context, *connect.Request[v1.UnlockWorkspaceRequest]) (*connect.Response[v1.UnlockWorkspaceResponse], error)
	// LockWorkspace closes SQLite, invalidates the session, and zeroes the in-memory DEK.
	LockWorkspace(context.Context, *connect.Request[v1.LockWorkspaceRequest]) (*connect.Response[v1.LockWorkspaceResponse], error)
	// ForgetRememberedWorkspace removes the unexpired OS-keystore item.
	ForgetRememberedWorkspace(context.Context, *connect.Request[v1.ForgetRememberedWorkspaceRequest]) (*connect.Response[v1.ForgetRememberedWorkspaceResponse], error)
	// GetWorkspaceState returns the bounded current installation projection.
	GetWorkspaceState(context.Context, *connect.Request[v1.GetWorkspaceStateRequest]) (*connect.Response[v1.GetWorkspaceStateResponse], error)
	// ChangePassphrase rewraps the existing DEK after current passphrase and new factor proof.
	ChangePassphrase(context.Context, *connect.Request[v1.ChangePassphraseRequest]) (*connect.Response[v1.ChangePassphraseResponse], error)
	// RecoverWorkspace performs closed-workspace break glass and sets a new passphrase.
	RecoverWorkspace(context.Context, *connect.Request[v1.RecoverWorkspaceRequest]) (*connect.Response[v1.RecoverWorkspaceResponse], error)
	// EstablishMovedWorkspaceTrust verifies the audit chain and creates a new OS mirror baseline.
	EstablishMovedWorkspaceTrust(context.Context, *connect.Request[v1.EstablishMovedWorkspaceTrustRequest]) (*connect.Response[v1.EstablishMovedWorkspaceTrustResponse], error)
	// BackupWorkspace starts a restart-safe encrypted backup job.
	BackupWorkspace(context.Context, *connect.Request[v1.BackupWorkspaceRequest]) (*connect.Response[v1.BackupWorkspaceResponse], error)
	// CancelBackup elects cancellation before the verified destination rename.
	CancelBackup(context.Context, *connect.Request[v1.CancelBackupRequest]) (*connect.Response[v1.CancelBackupResponse], error)
	// GetBackupJob returns one bounded persisted backup job.
	GetBackupJob(context.Context, *connect.Request[v1.GetBackupJobRequest]) (*connect.Response[v1.GetBackupJobResponse], error)
	// ListBackupJobs returns a stable bounded page of persisted backup jobs.
	ListBackupJobs(context.Context, *connect.Request[v1.ListBackupJobsRequest]) (*connect.Response[v1.ListBackupJobsResponse], error)
	// RestoreWorkspace starts or resumes one external-journal staged restore.
	RestoreWorkspace(context.Context, *connect.Request[v1.RestoreWorkspaceRequest]) (*connect.Response[v1.RestoreWorkspaceResponse], error)
	// GetRestoreStatus returns one fsync'd external-journal projection.
	GetRestoreStatus(context.Context, *connect.Request[v1.GetRestoreStatusRequest]) (*connect.Response[v1.GetRestoreStatusResponse], error)
	// ExportPreRestoreArchive starts an authorized encrypted predecessor-evidence export.
	ExportPreRestoreArchive(context.Context, *connect.Request[v1.ExportPreRestoreArchiveRequest]) (*connect.Response[v1.ExportPreRestoreArchiveResponse], error)
	// CancelPreRestoreArchiveExport elects cancellation before verified destination rename.
	CancelPreRestoreArchiveExport(context.Context, *connect.Request[v1.CancelPreRestoreArchiveExportRequest]) (*connect.Response[v1.CancelPreRestoreArchiveExportResponse], error)
	// GetPreRestoreArchiveExportJob returns one bounded persisted export job.
	GetPreRestoreArchiveExportJob(context.Context, *connect.Request[v1.GetPreRestoreArchiveExportJobRequest]) (*connect.Response[v1.GetPreRestoreArchiveExportJobResponse], error)
	// ListPreRestoreArchiveExportJobs returns a stable bounded export-job page.
	ListPreRestoreArchiveExportJobs(context.Context, *connect.Request[v1.ListPreRestoreArchiveExportJobsRequest]) (*connect.Response[v1.ListPreRestoreArchiveExportJobsResponse], error)
	// DeletePreRestoreArchive deletes eligible predecessor evidence after password, factor, reason, and age checks.
	DeletePreRestoreArchive(context.Context, *connect.Request[v1.DeletePreRestoreArchiveRequest]) (*connect.Response[v1.DeletePreRestoreArchiveResponse], error)
	// GetPreRestoreArchive returns retained encrypted-evidence metadata only.
	GetPreRestoreArchive(context.Context, *connect.Request[v1.GetPreRestoreArchiveRequest]) (*connect.Response[v1.GetPreRestoreArchiveResponse], error)
	// ListPreRestoreArchives returns a stable bounded archive page.
	ListPreRestoreArchives(context.Context, *connect.Request[v1.ListPreRestoreArchivesRequest]) (*connect.Response[v1.ListPreRestoreArchivesResponse], error)
	// TransferOwnership changes the owner, supersedes verification, invalidates sessions, and closes the workspace.
	TransferOwnership(context.Context, *connect.Request[v1.TransferOwnershipRequest]) (*connect.Response[v1.TransferOwnershipResponse], error)
}

